import org.junit.jupiter.api.io.TempDir;

class LmdbCountRecoveryCompatibilityTest {
	@TempDir
	Path directory;

	@Test
	void closeRecordsCompatibleCleanCountProofForRepeatedLegacyOpen() throws Exception {
		var vf = SimpleValueFactory.getInstance();
		var config = new LmdbStoreConfig().setInlineLiterals(false);
		ValueStore values = new ValueStore(directory.resolve("values").toFile(), config);
		try {
			values.startTransaction(true);
			values.storeValue(vf.createLiteral("persisted", vf.createIRI("urn:proof:datatype")));
			values.commit();
		} finally {
			values.close();
		}
		assertCleanMarker();
		values = new ValueStore(directory.resolve("values").toFile(), config);
		try {
			assertNotEquals(LmdbValue.UNKNOWN_ID,
					values.getId(vf.createLiteral("persisted", vf.createIRI("urn:proof:datatype"))));
		} finally {
			values.close();
		}
		assertCleanMarker();
	}

	@Test
	void implicitNestedCommitSurvivesLaterRollbackAndGc() throws Exception {
		var vf = SimpleValueFactory.getInstance();
		ValueStore values = new ValueStore(directory.resolve("values").toFile(),
				new LmdbStoreConfig().setInlineLiterals(false));
		try {
			var literal = vf.createLiteral("implicit component", vf.createIRI("urn:implicit:datatype"));
			var inner = vf.createTripleTerm(vf.createIRI("urn:implicit:inner"), vf.createIRI("urn:implicit:p"),
					literal);
			var outer = vf.createTripleTerm(vf.createIRI("urn:implicit:outer"), vf.createIRI("urn:implicit:p"), inner);
			long outerId = values.storeValue(outer);
			long innerId = values.getId(inner);
			long literalId = values.getId(literal);
			values.startTransaction(false);
			values.storeValue(vf.createLiteral("abort later", literal.getDatatype()));
			values.rollback();
			values.startTransaction(true);
			values.gcIds(List.of(innerId, literalId), new HashSet<>());
			values.commit();
			assertEquals(innerId, values.getId(inner), "The earlier native commit owns the nested term");
			assertEquals(literalId, values.getId(literal));
			assertEquals(outer, values.getValue(outerId));
		} finally {
			values.rollback();
			values.close();
		}
	}

	@Test
	void genuineOldWriterUndercountIsReconciledBeforeDeletingSharedOwners() throws Exception {
		extract("v2-unpatched-legacy-consistent-indexes.zip", directory);
		long datatypeId = LmdbCompatibilityFixtures.findReferenceId(directory, ValueIds.T_URI,
				"shared-custom-datatype".getBytes(StandardCharsets.UTF_8));
		byte[] encoded = nativeGet(directory, "ref_counts", LmdbCompatibilityFixtures.idKey(datatypeId));
		assertNotNull(encoded);
		assertEquals(1, Varint.readUnsigned(ByteBuffer.wrap(encoded)),
				"The authentic unpatched second transaction overwrote the earlier datatype owner count");
		var repository = LmdbV6InteroperabilityTest.repository(directory, false);
		repository.init();
		var vf = SimpleValueFactory.getInstance();
		var datatype = vf.createIRI("urn:v2:shared-custom-datatype");
		var surviving = vf.createLiteral("legacy writer value", datatype);
		try (var connection = repository.getConnection()) {
			ValueStore values = (ValueStore) repository.getValueFactory();
			connection.begin();
			connection.remove(vf.createIRI("urn:v2:first"), null, null);
			connection.remove(vf.createIRI("urn:v2:second"), null, null);
			connection.remove(vf.createBNode("shared-v2-bnode"), null, null);
			connection.commit();
			assertNotEquals(LmdbValue.UNKNOWN_ID, values.getId(surviving));
			assertEquals(surviving, values.getValue(values.getId(surviving)));
			assertEquals(datatypeId, values.getId(datatype));
			assertEquals(datatype, values.getValue(datatypeId));
		} finally {
			repository.shutDown();
		}
		assertCleanMarker();
	}

	private void assertCleanMarker() throws Exception {
		byte[] bytes = nativeGet(directory, "ref_counts", new byte[] { 0 });
		assertNotNull(bytes, "A known-correct patched close must avoid a full rebuild on the next open");
		assertEquals(18, bytes.length);
		ByteBuffer marker = ByteBuffer.wrap(bytes);
		assertEquals(0x52434654, marker.getInt());
		assertEquals(1, marker.get());
		assertEquals(1, marker.get());
		long generation = marker.getLong();
		assertNotEquals(0, generation);
		assertEquals(LmdbCompatibilityFixtures.nativeTransactionId(directory), generation,
				"Clean proof must describe the exact committed native dictionary generation");
		CRC32 crc = new CRC32();
		crc.update(bytes, 0, 14);
		assertEquals((int) crc.getValue(), marker.getInt());
	}
}
